import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi, } from "vitest";
import { ampTranscriptPath, isArmed } from "../chatSessions/arming.js";
import * as client from "../chatSessions/client.js";
import * as trackSkill from "../commands/trackSkill.js";
import { captureAmpAgentEnd, captureAmpAgentStart, captureAmpBitfabToolCall, captureAmpSessionStart, } from "./ampCapture.js";
const THREAD_ID = "T-amp-capture";
const PLUGIN_VERSION = "0.11.34";
const TEST_PLATFORM = {
    authPath: "amp",
    loginHint: "bitfab:setup login",
    setupHint: "bitfab:setup",
    updateHint: "bitfab:update",
    repo: "Project-White-Rabbit/bitfab-amp-plugin",
    remotePackageJsonPath: "package.json",
    cliBinary: "amp",
    displayName: "Amp",
    supportsAutoUpdate: true,
    marketplaceName: "bitfab",
    pluginName: "bitfab",
    marketplacePreRegistered: false,
    pluginUpdateCommands: ["amp plugins update bitfab"],
};
const MESSAGES = [
    { role: "user", id: 1, content: [{ type: "text", text: "fix my agent" }] },
    { role: "assistant", id: 2, content: [{ type: "text", text: "looking" }] },
];
function transcriptExists() {
    return fs.existsSync(ampTranscriptPath(THREAD_ID));
}
describe("Amp session capture", () => {
    let tempHome;
    let appendSpy;
    const originalHome = process.env.HOME;
    const originalEnv = process.env.BITFAB_CAPTURE_SESSIONS;
    beforeEach(() => {
        tempHome = fs.mkdtempSync(path.join(os.tmpdir(), "bitfab-amp-capture-"));
        process.env.HOME = tempHome;
        process.env.BITFAB_CAPTURE_SESSIONS = "1";
        appendSpy = vi.spyOn(client, "appendChatSession");
        appendSpy.mockImplementation(async (request) => ({
            ok: true,
            id: "chat-session-id",
            lastTranscriptOffset: request.toOffset,
            turnCount: request.turns.length,
        }));
        vi.spyOn(client, "getChatSessionState").mockResolvedValue(null);
    });
    afterEach(() => {
        process.env.HOME = originalHome;
        if (originalEnv === undefined) {
            delete process.env.BITFAB_CAPTURE_SESSIONS;
        }
        else {
            process.env.BITFAB_CAPTURE_SESSIONS = originalEnv;
        }
        vi.restoreAllMocks();
        fs.rmSync(tempHome, { recursive: true, force: true });
    });
    it("writes no transcript for a thread that never touched Bitfab", async () => {
        await captureAmpAgentStart({
            threadId: THREAD_ID,
            prompt: "hello there",
            platform: TEST_PLATFORM,
            pluginVersion: PLUGIN_VERSION,
        });
        await captureAmpAgentEnd({
            threadId: THREAD_ID,
            messages: MESSAGES,
            pluginVersion: PLUGIN_VERSION,
        });
        expect(isArmed(THREAD_ID)).toBe(false);
        expect(transcriptExists()).toBe(false);
        expect(appendSpy).not.toHaveBeenCalled();
    });
    it("writes no transcript when the user has not consented", async () => {
        process.env.BITFAB_CAPTURE_SESSIONS = "0";
        await captureAmpBitfabToolCall({
            threadId: THREAD_ID,
            pluginVersion: PLUGIN_VERSION,
        });
        await captureAmpAgentEnd({
            threadId: THREAD_ID,
            messages: MESSAGES,
            pluginVersion: PLUGIN_VERSION,
        });
        expect(isArmed(THREAD_ID)).toBe(false);
        expect(transcriptExists()).toBe(false);
        expect(appendSpy).not.toHaveBeenCalled();
    });
    it("arms on a Bitfab tool call and then captures the turn", async () => {
        await captureAmpBitfabToolCall({
            threadId: THREAD_ID,
            pluginVersion: PLUGIN_VERSION,
        });
        expect(isArmed(THREAD_ID)).toBe(true);
        await captureAmpAgentEnd({
            threadId: THREAD_ID,
            messages: MESSAGES,
            pluginVersion: PLUGIN_VERSION,
        });
        expect(appendSpy).toHaveBeenCalledTimes(1);
        const request = appendSpy.mock.calls[0][0];
        expect(request.agent).toBe("amp");
        expect(request.externalId).toBe(THREAD_ID);
        expect(request.turns.map((turn) => turn.role)).toEqual([
            "user",
            "assistant",
        ]);
    });
    it("reports the skill invocation to analytics, as the hook hosts do", async () => {
        const trackSpy = vi
            .spyOn(trackSkill, "runTrackSkill")
            .mockResolvedValue(undefined);
        await captureAmpAgentStart({
            threadId: THREAD_ID,
            prompt: "bitfab:assistant fix my failing traces",
            platform: TEST_PLATFORM,
            pluginVersion: PLUGIN_VERSION,
        });
        expect(trackSpy).toHaveBeenCalledWith("assistant", PLUGIN_VERSION, TEST_PLATFORM);
    });
    it("arms on a Bitfab skill prompt without a leading slash", async () => {
        await captureAmpAgentStart({
            threadId: THREAD_ID,
            prompt: "bitfab:setup instrument my agent",
            platform: TEST_PLATFORM,
            pluginVersion: PLUGIN_VERSION,
        });
        expect(isArmed(THREAD_ID)).toBe(true);
    });
    it("sends only the new turns on a second agent.end", async () => {
        await captureAmpBitfabToolCall({
            threadId: THREAD_ID,
            pluginVersion: PLUGIN_VERSION,
        });
        await captureAmpAgentEnd({
            threadId: THREAD_ID,
            messages: MESSAGES,
            pluginVersion: PLUGIN_VERSION,
        });
        const firstOffset = fs.statSync(ampTranscriptPath(THREAD_ID)).size;
        await captureAmpAgentEnd({
            threadId: THREAD_ID,
            pluginVersion: PLUGIN_VERSION,
            messages: [
                ...MESSAGES,
                { role: "user", id: 3, content: [{ type: "text", text: "and now?" }] },
            ],
        });
        const secondRequest = appendSpy.mock.calls[1][0];
        expect(secondRequest.turns.map((turn) => turn.content)).toEqual([[{ type: "text", text: "and now?" }]]);
        expect(secondRequest.fromOffset).toBe(firstOffset);
    });
    it("never marks an Amp session ended, leaving it to the server idle backstop", async () => {
        await captureAmpBitfabToolCall({
            threadId: THREAD_ID,
            pluginVersion: PLUGIN_VERSION,
        });
        await captureAmpAgentEnd({
            threadId: THREAD_ID,
            messages: MESSAGES,
            pluginVersion: PLUGIN_VERSION,
        });
        expect(appendSpy.mock.calls[0][0].ended).toBeUndefined();
    });
    it("keeps an armed thread armed when another thread starts before its first turn ends", async () => {
        await captureAmpBitfabToolCall({
            threadId: THREAD_ID,
            pluginVersion: PLUGIN_VERSION,
        });
        await captureAmpSessionStart({
            threadId: "T-another-thread",
            pluginVersion: PLUGIN_VERSION,
        });
        expect(isArmed(THREAD_ID)).toBe(true);
        await captureAmpAgentEnd({
            threadId: THREAD_ID,
            messages: MESSAGES,
            pluginVersion: PLUGIN_VERSION,
        });
        expect(appendSpy).toHaveBeenCalledTimes(1);
    });
    it("sweeps an Amp session armed over a week ago that never wrote a transcript", async () => {
        await captureAmpBitfabToolCall({
            threadId: THREAD_ID,
            pluginVersion: PLUGIN_VERSION,
        });
        const eightDaysAgo = new Date(Date.now() - 8 * 24 * 60 * 60 * 1000);
        fs.utimesSync(path.join(tempHome, ".config", "bitfab", "sessions", `${THREAD_ID}.armed`), eightDaysAgo, eightDaysAgo);
        await captureAmpSessionStart({
            threadId: "T-another-thread",
            pluginVersion: PLUGIN_VERSION,
        });
        expect(isArmed(THREAD_ID)).toBe(false);
    });
});
